import { useCallback, useEffect, useRef, useState } from "react"

/**
 * The game-show shell the generated quiz and flashcard sets are played in.
 *
 * Both used to be a card on a page: a form-width column, a question in body
 * type, radio buttons, Back and Continue. That reads as a form to fill in, and
 * a ten-item practice set generated by the tutor is not a form -- it is a
 * round. This is the same attempt, the same endpoints and the same scoring,
 * drawn as one: the whole window, one question at a time, four coloured tiles,
 * and a clock that does not wait for you.
 *
 * The clock is the part that changes how it is played. A practice set with no
 * timer is answered by re-reading the question until you are sure, which is
 * revision, not recall. Running out of time submits what is selected -- blank
 * if nothing is -- and the server scores that as wrong, exactly as it would a
 * wrong answer typed slowly.
 */

/** Kahoot's four, in the brand's own hues. Shape carries the answer, not colour
 *  alone -- the tiles have to be distinguishable to a colour-blind player. */
export const ANSWER_TILES = [
  { key: "triangle", face: "var(--color-rb-cardinal)", lip: "var(--color-rb-cardinal-lip)" },
  { key: "diamond", face: "var(--color-rb-feather)", lip: "var(--color-rb-feather-lip)" },
  { key: "circle", face: "var(--color-rb-fox)", lip: "var(--color-rb-fox-lip)" },
  { key: "square", face: "var(--color-rb-leaf)", lip: "var(--color-rb-leaf-lip)" },
]

function TileShape({ shape, className = "" }) {
  const common = { className, viewBox: "0 0 24 24", "aria-hidden": "true", fill: "currentColor" }

  switch (shape) {
    case "triangle":
      return (
        <svg {...common}>
          <path d="M12 3 22 21H2z" />
        </svg>
      )
    case "diamond":
      return (
        <svg {...common}>
          <path d="M12 2 22 12 12 22 2 12z" />
        </svg>
      )
    case "circle":
      return (
        <svg {...common}>
          <circle cx="12" cy="12" r="9.5" />
        </svg>
      )
    default:
      return (
        <svg {...common}>
          <rect x="3" y="3" width="18" height="18" rx="2" />
        </svg>
      )
  }
}

/**
 * A countdown that survives re-renders and restarts when `resetKey` changes.
 *
 * `onExpire` is held in a ref rather than listed as a dependency: it is a new
 * closure on every render, and depending on it would tear down and restart the
 * interval several times a second -- a clock that never reaches zero.
 */
export function useCountdown({ seconds, resetKey, running = true, onExpire }) {
  const [remaining, setRemaining] = useState(seconds)
  const expireRef = useRef(onExpire)
  expireRef.current = onExpire

  useEffect(() => {
    setRemaining(seconds)
  }, [seconds, resetKey])

  useEffect(() => {
    if (!running) return undefined

    const started = Date.now()
    const interval = setInterval(() => {
      const left = seconds - Math.floor((Date.now() - started) / 1000)

      if (left <= 0) {
        clearInterval(interval)
        setRemaining(0)
        expireRef.current?.()
        return
      }

      setRemaining(left)
    }, 250)

    return () => clearInterval(interval)
  }, [seconds, resetKey, running])

  return remaining
}

/** The clock, as a ring that empties. Colour turns urgent under five seconds. */
export function CountdownRing({ remaining, total, paused = false }) {
  const safeTotal = Math.max(1, total)
  const fraction = Math.max(0, Math.min(1, remaining / safeTotal))
  const circumference = 2 * Math.PI * 26
  const urgent = !paused && remaining <= 5

  return (
    <div className="relative grid size-16 shrink-0 place-items-center">
      <svg viewBox="0 0 60 60" className="size-16 -rotate-90">
        <circle cx="30" cy="30" r="26" fill="none" stroke="rgba(255,255,255,0.2)" strokeWidth="6" />
        <circle
          cx="30"
          cy="30"
          r="26"
          fill="none"
          stroke={urgent ? "var(--color-rb-cardinal)" : "#ffffff"}
          strokeWidth="6"
          strokeLinecap="round"
          strokeDasharray={circumference}
          strokeDashoffset={circumference * (1 - fraction)}
          className="transition-[stroke-dashoffset] duration-300 ease-linear"
        />
      </svg>

      {/* Frozen, not blanked. A dash where a number was reads as a broken
          clock; the stopped number says the round moved on. */}
      <span
        className={`absolute font-rb-display text-xl font-extrabold tabular-nums ${
          urgent ? "text-rb-cardinal" : "text-white"
        } ${paused ? "opacity-50" : ""}`}
      >
        {remaining}
      </span>
    </div>
  )
}

/**
 * One answer. `state` is what the tile knows after the answer is locked in:
 * "correct" and "wrong" stay lit, everything else dims out of the way.
 */
export function AnswerTile({ index, label, selected, state, disabled, onSelect }) {
  const tile = ANSWER_TILES[index % ANSWER_TILES.length]
  const dimmed = state === "dimmed"

  return (
    <button
      type="button"
      disabled={disabled}
      onClick={onSelect}
      aria-pressed={selected}
      style={{ background: tile.face, boxShadow: `0 6px 0 0 ${tile.lip}` }}
      className={`flex min-h-28 items-center gap-4 rounded-2xl px-5 py-4 text-left text-white transition duration-150 focus-visible:outline-3 focus-visible:outline-offset-4 focus-visible:outline-white enabled:hover:-translate-y-0.5 enabled:active:translate-y-0.5 enabled:active:shadow-none ${
        dimmed ? "opacity-35 saturate-50" : ""
      } ${selected ? "ring-4 ring-white ring-offset-2 ring-offset-transparent" : ""}`}
    >
      <TileShape shape={tile.key} className="size-8 shrink-0 drop-shadow" />

      <span className="font-rb-display text-lg leading-6 font-extrabold sm:text-xl">
        {label}
      </span>

      {state === "correct" ? (
        <span className="ml-auto font-rb-display text-sm font-extrabold uppercase tracking-wide">
          Correct
        </span>
      ) : null}
    </button>
  )
}

/**
 * The full-window frame: a dark arena so the coloured tiles carry the screen,
 * with the run's own state along the top.
 *
 * `min-h-dvh` rather than `min-h-screen`: on a phone the browser's own chrome
 * eats enough of `100vh` to push the last tile under the fold.
 */
export function ArenaShell({ children, header }) {
  return (
    <main className="flex min-h-dvh flex-col bg-[linear-gradient(160deg,#1B1F3B_0%,#2A1F5B_45%,#12142B_100%)] px-4 py-4 text-white sm:px-6">
      {header}
      <div className="mx-auto flex w-full max-w-5xl flex-1 flex-col">{children}</div>
    </main>
  )
}

export function ArenaHeader({ title, subtitle, position, total, onLeave, right }) {
  return (
    <header className="mx-auto flex w-full max-w-5xl items-center gap-4 pb-4">
      <button
        type="button"
        onClick={onLeave}
        className="rounded-full border border-white/25 px-4 py-2 font-rb-display text-xs font-extrabold uppercase tracking-wide text-white/85 transition hover:bg-white/10 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white"
      >
        Leave
      </button>

      <div className="min-w-0 flex-1">
        <p className="truncate font-rb-display font-extrabold">{title}</p>
        <p className="truncate text-xs text-white/70">{subtitle}</p>
      </div>

      <span className="rounded-full bg-white/15 px-3 py-1 font-rb-display text-sm font-extrabold tabular-nums">
        {position} / {total}
      </span>

      {right}
    </header>
  )
}

/**
 * Points for being both right and quick, the way the format is played.
 *
 * Deliberately NOT sent anywhere. The attempt's real score is correctness, and
 * the server awards the XP and coins from that -- inventing a second number and
 * persisting it would give a learner two scores for one run that disagree. This
 * one lives for the length of the round and is labelled as such on the results
 * screen.
 */
export function speedPoints({ correct, remaining, total }) {
  if (!correct) return 0
  const safeTotal = Math.max(1, total)
  return 500 + Math.round(500 * Math.max(0, Math.min(1, remaining / safeTotal)))
}

/** A stable per-question key, so the countdown restarts on every question. */
export function useQuestionClock({ seconds, index, running, onExpire }) {
  const expire = useCallback(() => onExpire?.(), [onExpire])
  return useCountdown({ seconds, resetKey: index, running, onExpire: expire })
}
